const fs = require('fs');
const path = require('path');
const statePath = path.join(process.cwd(), '.v1', 'state.json');

try {
  const raw = fs.readFileSync(statePath, 'utf-8');
  const state = JSON.parse(raw);

  console.log('Current hypotheses length:', state.hypotheses?.length ?? 'undefined');

  if (!state.hypotheses) {
    state.hypotheses = [];
  }

  state.hypotheses.push({
    id: 'hyp-1',
    description: 'The invalidateCache() method in TaskManager has its cache invalidation code commented out (lines 90-93 of src/task-manager.ts), so the statusCache is never invalidated after task mutations (createTask, updateTask, deleteTask, clear). This causes filterByStatus() to return stale cached results.',
    evidence: ['src/task-manager.ts:90-93 - invalidateCache method body is commented out', 'src/task-manager.ts:27,49,71,87 - invalidateCache is called after mutations but does nothing', 'tests/task-manager.test.ts:52-63 - test filterByStatus returns correct tasks and not stale'],
    confidence: 0.99,
    status: 'selected',
    files: ['src/task-manager.ts']
  });

  state.selectedHypothesis = 'hyp-1';

  fs.writeFileSync(statePath, JSON.stringify(state, null, 2));
  console.log('Updated hypotheses length:', state.hypotheses.length);
} catch (e) {
  console.error('Error:', e.message);
}
